import{_ as s}from"./chunks/Audio.COine8Wh.js";import{c as i,o as a,j as t,G as o,ae as n,a as r}from"./chunks/framework.Bw0Gm4PQ.js";const u=JSON.parse('{"title":"TAKING STEPS TO END CASHLESS BAIL TO PROTECT AMERICANS","description":"","frontmatter":{"legisId":"2025-08-25-taking-steps-to-end-cashless-bail-to-protect-americans","title":"TAKING STEPS TO END CASHLESS BAIL TO PROTECT AMERICANS","sourceUrl":"https://www.whitehouse.gov/presidential-actions/2025/08/taking-steps-to-end-cashless-bail-to-protect-americans/","publishDate":"2025-08-25T11:24:19-04:00"},"headers":[],"relativePath":"executive-orders/2025-08-25-taking-steps-to-end-cashless-bail-to-protect-americans.md","filePath":"executive-orders/2025-08-25-taking-steps-to-end-cashless-bail-to-protect-americans.md"}'),l={name:"executive-orders/2025-08-25-taking-steps-to-end-cashless-bail-to-protect-americans.md"},g=Object.assign(l,{setup(c){return(d,e)=>(a(),i("div",null,[e[0]||(e[0]=t("h1",{id:"taking-steps-to-end-cashless-bail-to-protect-americans",tabindex:"-1"},[r("TAKING STEPS TO END CASHLESS BAIL TO PROTECT AMERICANS "),t("a",{class:"header-anchor",href:"#taking-steps-to-end-cashless-bail-to-protect-americans","aria-label":'Permalink to "TAKING STEPS TO END CASHLESS BAIL TO PROTECT AMERICANS"'},"​")],-1)),o(s),e[1]||(e[1]=n('<p>Published on Monday, August 25, 2025</p><ul><li><p><strong>Presidential Authority</strong>: The order is issued by the President based on constitutional authority and U.S. laws.</p></li><li><p><strong>Public Safety Focus</strong>: The order emphasizes the need to incarcerate individuals who pose a clear ongoing risk to society due to pending criminal charges or criminal history.</p></li><li><p><strong>Critique of Cashless Bail</strong>: It argues that releasing individuals without bail under local policies endangers public safety and wastes law enforcement resources.</p></li><li><p><strong>Federal Policy Change</strong>: The Administration&#39;s policy will no longer support jurisdictions with cashless bail policies to enhance safety.</p></li><li><p><strong>Action Items</strong>:</p><ul><li><strong>List of Jurisdictions</strong>: The Attorney General must submit a list within 30 days identifying states and localities that have substantially eliminated cash bail for serious offenses.</li><li><strong>Funding Review</strong>: Federal departments and agencies will identify and potentially suspend or terminate funding to these cashless bail jurisdictions.</li></ul></li><li><p><strong>Order Limitations</strong>:</p><ul><li>The order does not affect existing legal authorities or functions of the Office of Management and Budget.</li><li>It must align with applicable law and available appropriations.</li><li>The order does not create enforceable rights or benefits for any party against the U.S. or its entities.</li></ul></li><li><p><strong>Publication Costs</strong>: The Department of Justice will cover the costs for publication of the order.</p></li></ul><p>Source: <a href="https://www.whitehouse.gov/presidential-actions/2025/08/taking-steps-to-end-cashless-bail-to-protect-americans/" target="_blank" rel="noreferrer">https://www.whitehouse.gov/presidential-actions/2025/08/taking-steps-to-end-cashless-bail-to-protect-americans/</a></p>',3))]))}});export{u as __pageData,g as default};
